#include <iostream> 
#include <fstream> 
#include <string> 
#include <map> 

using namespace std; 

int main() 
{ 
    string line; 
    map<string, int> counts; 

    // Open file 
    ifstream fin("file.txt"); 

    // Read each line 
    while (getline(fin, line)) { 
        istringstream iss(line); 
        string word; 
        int count = 0; 

        // Read each word 
        while (iss >> word) { 
            if (count == 0) 
                counts[word] = 0; 
            else 
                counts[word]++; 

            count++; 
        } 
    } 

    // Print the results 
    for (map<string, int>::const_iterator itr = counts.begin(); itr != counts.end(); itr++) 
        cout << itr->first << " -> " << itr->second << endl; 

    return 0; 
}

