def longest_common_subsequence(str1, str2): 
    # Initialise result to 0 
    result = 0
    # Initialize dp array 
    dp = [[0 for x in range(len(str1)] for y in range(len(str2))] 

    # Filling the dp array 
    for i in range(len(str1)): 
        for j in range(len(str2)): 
            if i == 0 or j == 0: 
                dp[i][j] = 0
            elif str1[i-1] == str2[j-1]: 
                dp[i][j] = dp[i-1][j-1] + 1
            else: 
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) 

    # Finding the result 
    for i in range(len(str1)): 
        for j in range(len(str2)): 
            if dp[i][j] > result: 
                result = dp[i][j] 

    return result 

