class Queue:
    def __init__(self):
        self.front = None
        self.back = None

    def enqueue(self, item):
        #Push a new item to the front of the queue
        if self.front is None:
            self.front = item
        else:
            self.back.next = item
            self.back = item

    def dequeue(self):
        #Pop the current item from the front of the queue
        if self.front is not None:
            temp = self.front
            self.front = self.front.next
            return temp
        return None

    def is_empty(self):
        #Return True if the queue is empty
        if self.back is None:
            return True
        return False

    def __str__(self):
        #Return a string representation of the queue
        if self.back is None:
            return 'Empty Queue'
        temp = self.back
        self.back = self.back.next
        return '[Front: ' + temp + ' Back: ' + self.back)

